using backend.Tests.Helpers;
using FluentAssertions;
using NUnit.Framework;
using System.Net;
using System.Net.Http.Json;

namespace backend.Tests.Integration;

/// <summary>
/// Rate limiting on the guest endpoints.
///
/// The exposure
/// ------------
/// /api/guest/chat runs the same pipeline as an authenticated analysis — Groq
/// domain classification followed by Gemini insight generation — with no
/// account, no plan and no quota. It was completely unmetered.
///
/// sessionId offered no protection: it is generated by the browser, never
/// verified, and only used to name a temp file. A caller loops with a fresh
/// GUID each time and every iteration spends real tokens. The limiter therefore
/// partitions on client IP, which is the only thing in the request the caller
/// does not choose.
///
/// These tests share one factory across the fixture on purpose. The limiter's
/// window state lives in the server, so a per-test factory would reset the
/// count and the limit would never be reached.
/// </summary>
[TestFixture]
public class GuestRateLimitTests
{
    private TestWebApplicationFactory _factory = null!;
    private HttpClient _client = null!;

    private static readonly string GuestTempDir =
        Path.Combine(Path.GetTempPath(), "dig_guest");

    [OneTimeSetUp]
    public void OneTimeSetUp()
    {
        _factory = new TestWebApplicationFactory();
        _client  = _factory.CreateClient();
        Directory.CreateDirectory(GuestTempDir);
    }

    [OneTimeTearDown]
    public void OneTimeTearDown()
    {
        _client.Dispose();
        _factory.Dispose();
    }

    private Task<HttpResponseMessage> PostChat() =>
        _client.PostAsJsonAsync("/api/guest/chat", new
        {
            message   = "start_analysis",
            sessionId = Guid.NewGuid().ToString(),   // a fresh id every call
            fileName  = "data.csv",
        });

    [Test, Order(1)]
    public async Task GuestChat_IsRateLimited_EvenWithAFreshSessionIdEachTime()
    {
        // Risk: this is the whole point. Rotating sessionId must not reset the
        // budget, or the limit is decorative.
        var statuses = new List<HttpStatusCode>();

        for (var i = 0; i < 12; i++)
            statuses.Add((await PostChat()).StatusCode);

        statuses.Should().Contain(HttpStatusCode.TooManyRequests,
            "a client rotating sessionId must still hit the per-IP limit");
    }

    [Test, Order(2)]
    public async Task RateLimitedResponse_CarriesRetryAfter()
    {
        // Risk: a 429 with no Retry-After leaves a well-behaved client guessing,
        // and most of them retry immediately — which is the behaviour the limit
        // exists to prevent.
        HttpResponseMessage? limited = null;
        for (var i = 0; i < 12 && limited is null; i++)
        {
            var res = await PostChat();
            if (res.StatusCode == HttpStatusCode.TooManyRequests) limited = res;
        }

        limited.Should().NotBeNull("the limit should already be exhausted by now");
        limited!.Headers.Contains("Retry-After").Should().BeTrue();
    }

    [Test, Order(3)]
    public async Task RateLimitedResponse_IsMachineReadableAndLeaksNothing()
    {
        HttpResponseMessage? limited = null;
        for (var i = 0; i < 12 && limited is null; i++)
        {
            var res = await PostChat();
            if (res.StatusCode == HttpStatusCode.TooManyRequests) limited = res;
        }

        var body = await limited!.Content.ReadAsStringAsync();

        body.Should().Contain("RATE_LIMITED", "clients need a stable code to branch on");
        body.Should().NotContain("Exception");
        body.Should().NotContain("at backend.", "no stack frames in a rejection");
    }

    [Test, Order(4)]
    public async Task HealthEndpointStaysReachableWhileGuestChatIsLimited()
    {
        // Risk: a global limiter sized too tightly, or a policy applied at the
        // wrong scope, would take health checks down with it — and a load
        // balancer would then pull a healthy instance out of rotation.
        var response = await _client.GetAsync("/health");

        response.StatusCode.Should().Be(HttpStatusCode.OK);
    }
}
